# 1. Find exact repeats: tandem repeats
import re
def find_tandem(seq, min_unit=8, min_copies=2):
    res=[]
    n=len(seq)
    for u in range(min_unit, 60):
        i=0
        while i+u*min_copies<=n:
            unit=seq[i:i+u]
            cnt=1
            j=i+u
            while j+u<=n and seq[j:j+u]==unit:
                cnt+=1; j+=u
            if cnt>=min_copies:
                res.append((i+1,j,unit,cnt))
                i=j
            else:
                i+=1
    return res

