def orfs(seq, minnt=300):
    res=[]
    for strand,s in [('+',seq),('-',rc(seq))]:
        for f in range(3):
            i=f
            while i < len(s)-2:
                if s[i:i+3] in ('ATG',):
                    j=i
                    while j < len(s)-2:
                        cod=s[j:j+3]
                        if cod in ('TAA','TAG','TGA'):
                            break
                        j+=3
                    if j+3-i >= minnt:
                        res.append((strand,f,i+1,j+3,j+3-i,i))
                    i=j+3
                else:
                    i+=3
    return res

